aufrufe = 0

def fib(n):
    global aufrufe
    aufrufe += 1
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

print(fib(20))    # 6765
print(aufrufe)    # 21891

memo = {}

def fib_m(n):
    if n < 2:
        return n
    if n in memo:
        return memo[n]
    memo[n] = fib_m(n - 1) + fib_m(n - 2)
    return memo[n]

print(fib_m(80))  # 23416728348467685

def potenz(x, n):
    if n == 0:
        return 1
    if n % 2 == 0:
        h = potenz(x, n // 2)
        return h * h
    return x * potenz(x, n - 1)

print(potenz(2, 10))   # 1024

def suche(liste, ziel, li, re):
    if li > re:
        return -1          # nicht da
    mitte = (li + re) // 2
    if liste[mitte] == ziel:
        return mitte
    if ziel < liste[mitte]:
        return suche(liste, ziel,
                     li, mitte - 1)
    return suche(liste, ziel,
                 mitte + 1, re)

punkte = [12, 25, 31, 47, 58, 63, 77]
print(suche(punkte, 58, 0, 6))  # 4
print(suche(punkte, 50, 0, 6))  # -1

